INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','easy','flashcard','Where do all blood cells originate, and what is the name of the cell they come from?','["All blood cells originate in the bone marrow from the multipotential haematopoietic stem cell (MHSC). This single cell type gives rise to every circulating blood cell lineage through successive divisions and differentiation steps."]','A','Mnemonic: ONE cell, ALL blood. The MHSC is the foundation of haematopoiesis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','easy','flashcard','Describe the sites of red blood cell production across the human lifespan.','["Embryo: yolk sac (early weeks). Middle trimester: liver is the main site with some production in spleen and lymph nodes. Last month of gestation and after birth: exclusively bone marrow. By age 5, all bones produce RBCs. After age 20, only membranous bones (vertebrae, sternum, ribs, ilia) remain active."]','A','Mnemonic: Yolk sac → Liver → Bone Marrow across the lifespan.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','medium','flashcard','What is the difference between a growth inducer and a differentiation inducer in haematopoiesis?','["Growth inducers (e.g., interleukin-3) stimulate proliferation of committed stem cells without causing differentiation. Differentiation inducers cause one type of committed stem cell to progress one or more steps toward a final mature blood cell. Both classes are produced under signals from outside the bone marrow."]','A','IL-3 promotes growth of virtually all committed stem cell types — the broadest growth inducer.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','medium','flashcard','What is a colony-forming unit (CFU) in haematopoiesis and give two examples?','["A CFU is a committed stem cell that when cultured produces a colony of one specific blood cell type. Examples: CFU-E (erythrocyte) produces red blood cells; CFU-GM (granulocyte/monocyte) produces granulocytes and monocytes; CFU-M (megakaryocyte) produces platelets."]','A','CFUs are committed progenitors — unlike the MHSC, each CFU is locked into one lineage.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','medium','flashcard','What is erythropoietin (EPO), where is it produced, and what triggers its secretion?','["Erythropoietin (EPO) is a glycoprotein hormone (MW ~34,000) produced mainly by fibroblast-like interstitial cells in the renal cortex (~90%) with the remainder from the liver. Hypoxia triggers increased tissue levels of HIF-1, which binds the EPO gene hypoxia-response element, inducing EPO synthesis. EPO then stimulates proerythroblast production from haematopoietic stem cells."]','A','90% kidney, 10% liver. Bilateral nephrectomy causes severe anaemia because the liver alone cannot maintain adequate RBC production.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','hard','flashcard','What is the role of HIF-1 in erythropoietin regulation?','["Hypoxia-inducible factor-1 (HIF-1) is a transcription factor whose levels rise in renal tissue during hypoxia. HIF-1 binds to a hypoxia-response element in the erythropoietin gene, inducing transcription of EPO mRNA and increasing EPO synthesis. EPO then acts on bone marrow to accelerate RBC production."]','A','HIF-1 is the molecular oxygen sensor. Prolyl hydroxylases normally tag HIF-1 for degradation in normoxia — hypoxia blocks this, allowing HIF-1 to accumulate.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','medium','flashcard','What are the five key cytokines that regulate granulocyte and monocyte production during inflammation?','["The five dominant regulators are: (1) Tumour Necrosis Factor (TNF); (2) Interleukin-1 (IL-1); (3) GM-CSF — stimulates both granulocyte and monocyte production; (4) G-CSF — stimulates granulocyte production; (5) M-CSF — stimulates monocyte production. All are produced by activated macrophages in inflamed tissue."]','A','Mnemonic: TIG3 — TNF, IL-1, G-CSF, GM-CSF, M-CSF. These create a powerful feedback from inflammation to marrow.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','easy','flashcard','What vitamins are essential for red blood cell maturation and why?','["Vitamin B12 (cyanocobalamin) and folic acid are both essential for RBC maturation. They are required for synthesis of thymidine triphosphate, a building block of DNA. Without them, DNA synthesis is impaired, erythroblasts cannot divide normally, and large fragile macrocytes are produced — maturation failure anaemia (megaloblastic anaemia)."]','A','Both converge on DNA synthesis. B12 deficiency also causes neurological damage; folate deficiency does not — a key distinguishing feature.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','hard','flashcard','Explain the role of intrinsic factor in vitamin B12 absorption.','["Intrinsic factor is a glycoprotein secreted by gastric parietal cells. It binds tightly to dietary vitamin B12, protecting it from gastrointestinal digestion. The B12-intrinsic factor complex then binds to specific receptors on ileal brush-border membranes and B12 is absorbed by pinocytosis. Without intrinsic factor (e.g., pernicious anaemia), B12 cannot be absorbed, leading to megaloblastic anaemia."]','A','Pernicious anaemia = atrophic gastric mucosa → no intrinsic factor → no B12 absorption. B12 stores last 3-4 years; folate stores last only weeks.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','medium','flashcard','What are the two major white blood cell lineages and where are cells of each produced?','["The two major WBC lineages are: (1) Myelocytic lineage — granulocytes (neutrophils, eosinophils, basophils) and monocytes, produced exclusively in the bone marrow; (2) Lymphocytic lineage — lymphocytes and plasma cells, produced mainly in lymphoid tissues (lymph nodes, spleen, thymus, tonsils, Peyer patches). T lymphocytes are preprocessed in the thymus; B lymphocytes in liver (fetal) and bone marrow (postnatal)."]','A','Myelo = Marrow; Lympho = Lymphoid tissues + thymus preprocessing.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','easy','flashcard','Describe the normal shape and dimensions of a red blood cell.','["Normal RBCs are biconcave discs with a mean diameter of ~7.8 micrometres and thickness of 2.5 micrometres at the thickest point and ~1 micrometre in the centre. Average volume: 90-95 cubic micrometres. The biconcave shape and excess membrane allow RBCs to deform without rupturing as they squeeze through capillaries."]','A','The biconcave disc maximises surface area for gas exchange while maintaining deformability. Loss of this shape (e.g., spherocytosis, sickling) leads to haemolysis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','easy','flashcard','What is the normal RBC count in adult men and women?','["Normal RBC count: Men approximately 5,200,000 per cubic millimetre (±300,000). Women approximately 4,700,000 per cubic millimetre (±300,000). People at high altitudes have higher counts due to chronic hypoxia stimulating EPO secretion."]','A','Men > Women due to testosterone-driven EPO stimulation. Always check altitude and physiological context when interpreting RBC counts.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','medium','flashcard','What is the normal haematocrit and how much haemoglobin does whole blood contain?','["Normal haematocrit (packed cell volume): 40-45%. Haemoglobin concentration: Men average 15 g/100 ml whole blood; Women average 14 g/100 ml. RBCs can concentrate haemoglobin up to 34 g/100 ml of cells — the metabolic ceiling of the haemoglobin-forming mechanism."]','A','Haematocrit reflects RBC proportion of blood volume. Low haematocrit + low Hb = anaemia. High haematocrit = polycythaemia.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','easy','flashcard','What is the normal lifespan of a red blood cell and how are old RBCs destroyed?','["RBCs survive an average of 120 days. As they age, metabolic enzyme systems become less active, membranes become more fragile, and cells rupture — many in the spleen where trabeculae are only 3 micrometres wide compared with the 8-micrometre RBC diameter. Released haemoglobin is phagocytised by macrophages (Kupffer cells in liver, spleen macrophages); iron is recycled via transferrin; porphyrin is converted to bilirubin."]','A','Mnemonic: RBCs last 120 days — roughly 4 months. Spleen = RBC graveyard. Iron is recycled; porphyrin becomes bilirubin.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','medium','flashcard','What are the non-oxygen-transport functions of red blood cells?','["RBCs serve two additional major functions: (1) CO2 transport — RBCs contain large quantities of carbonic anhydrase, catalysing CO2 + H2O ⇌ H2CO3, enabling blood to carry CO2 as bicarbonate ions (HCO3−) to the lungs; (2) Acid-base buffering — haemoglobin is an excellent acid-base buffer, making RBCs responsible for most of the buffering capacity of whole blood."]','A','Carbonic anhydrase accelerates the CO2-bicarbonate reaction thousands of fold. Without RBCs, CO2 transport would be severely impaired.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','medium','flashcard','Describe the stages of red blood cell development from earliest precursor to mature erythrocyte.','["Stages: Proerythroblast → Basophil erythroblast (stains with basic dyes) → Polychromatophil erythroblast (haemoglobin first appears) → Orthochromatic erythroblast (nucleus condenses) → Reticulocyte (nucleus extruded; released into blood with remnant Golgi/mitochondria) → Mature erythrocyte (basophilic material disappears within 1-2 days). Reticulocytes normally constitute less than 1% of circulating RBCs."]','A','Reticulocyte count is a marker of bone marrow activity. Elevated reticulocytes indicate increased RBC production (e.g., after haemorrhage or haemolysis).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','hard','flashcard','How does severe anaemia affect the cardiovascular system?','["In severe anaemia: (1) Blood viscosity falls (as low as 1.5x water vs. normal 3x), reducing peripheral vascular resistance; (2) Hypoxia causes peripheral vasodilation, further reducing resistance; (3) Both increase venous return and cardiac output — sometimes 3-4 times normal; (4) The increased cardiac workload means exercise can precipitate acute cardiac failure because the heart cannot pump further beyond its already elevated output."]','A','Anaemia → low viscosity + vasodilation → high output state → cardiac strain. Treat the underlying cause and support the heart.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','easy','flashcard','What is secondary polycythaemia and what causes it?','["Secondary polycythaemia is a physiological increase in RBC count (commonly 6-7 million/mm3) caused by chronic tissue hypoxia — e.g., high altitude (14,000-17,000 feet) or cardiac/pulmonary failure. Hypoxia stimulates EPO secretion which drives increased RBC production. It is distinguished from polycythaemia vera which is a clonal malignancy."]','A','Secondary polycythaemia = physiological response to hypoxia via EPO. Polycythaemia vera = pathological autonomous overproduction independent of EPO.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','medium','flashcard','What metabolic functions do mature RBC enzymes perform to keep the cell viable?','["Mature RBCs lack nucleus, mitochondria, and endoplasmic reticulum but retain cytoplasmic enzymes that metabolise glucose and produce small amounts of ATP. These enzymes: (1) maintain pliability of the cell membrane; (2) maintain membrane ion transport; (3) keep iron in ferrous (Fe2+) rather than ferric (Fe3+) state; (4) prevent oxidation of RBC proteins. As these systems wear out over 120 days, the cell becomes fragile and is destroyed."]','A','No nucleus = no new protein synthesis. RBCs rely entirely on pre-existing enzymes. G6PD deficiency causes enzyme failure leading to haemolytic anaemia.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','hard','flashcard','What is aplastic anaemia and what are its main causes?','["Aplastic anaemia results from bone marrow failure leading to inadequate RBC production. Causes: (1) High-dose radiation or chemotherapy damaging bone marrow stem cells; (2) Toxic chemicals (e.g., benzene, insecticides); (3) Autoimmune disorders (e.g., lupus erythematosus) where the immune system attacks bone marrow stem cells; (4) Idiopathic — about half of cases. Treatment: blood transfusions (temporary) or bone marrow transplantation."]','A','Aplastic anaemia = pancytopenia (affects all cell lines). Distinguish from pure red cell aplasia, which selectively spares WBCs and platelets.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','easy','flashcard','What is the molecular structure of haemoglobin A (HbA)?','["Haemoglobin A consists of four chains: two alpha and two beta chains, each containing a heme group with one iron atom (MW 64,458). Each iron atom binds one oxygen molecule, so each Hb molecule carries four O2 molecules. Synthesis: succinyl-CoA + glycine → pyrrole → protoporphyrin IX + Fe2+ → heme + globin chain → Hb chain. Two alpha chains + two beta chains loosely combine → HbA."]','A','HbA = 2α + 2β. HbF = 2α + 2γ (higher O2 affinity). HbA2 = 2α + 2δ. HbS = 2α + 2β(Val6Glu mutation).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','easy','flashcard','How much oxygen can each gram of haemoglobin carry and what is the total O2 carrying capacity of blood?','["Each gram of haemoglobin can combine with 1.34 ml of oxygen when 100% saturated. With haemoglobin concentration of ~15 g/100 ml (men), blood can carry approximately 20 ml O2 per 100 ml blood. In women (~14 g/100 ml Hb), the capacity is ~19 ml O2/100 ml blood. Dissolved plasma contributes only ~0.3 ml/100 ml."]','A','Formula: O2 capacity = [Hb] x 1.34 x SaO2. At sea level, SaO2 ~98%, so effective capacity ~19.6 ml/100 ml in men.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','medium','flashcard','How does haemoglobin bind and release oxygen?','["Oxygen binds loosely and reversibly to a coordination bond of the iron atom in each heme group — not to the iron positive valence bonds. The oxygen is carried as molecular O2 (not ionic) and released in molecular form in the peripheral tissues where oxygen tension is low. Hb loads O2 in the high-PO2 lungs and unloads it in the low-PO2 tissues."]','A','The binding is loose and reversible — crucial for function. CO binds the same site 200x more tightly than O2, which is why CO poisoning is so dangerous.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','hard','flashcard','What is the molecular defect in sickle cell anaemia (HbS) and what are its consequences?','["In sickle cell anaemia, valine is substituted for glutamic acid at position 6 of both beta chains. When HbS is exposed to low oxygen tension, it forms elongated crystals (up to 15 um long) inside RBCs. These crystals distort cells into a sickle shape, block small capillaries, damage cell membranes, and cause haemolysis. A sickle cell crisis is a vicious cycle: low O2 → sickling → haemolysis → more hypoxia → more sickling and RBC destruction."]','A','Val replaces Glu at beta6 — a hydrophobic for charged amino acid swap. The sticky hydrophobic patches cause HbS polymerisation under deoxygenation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','medium','flashcard','What is haemoglobin F (HbF) and why does it have a higher oxygen affinity than HbA?','["Haemoglobin F consists of two alpha and two gamma chains (vs. HbA beta chains). HbF has higher oxygen affinity than HbA because gamma chains bind 2,3-BPG less avidly than beta chains. Reduced 2,3-BPG binding means less stabilisation of the deoxygenated state, shifting the O2-dissociation curve leftward. This allows HbF to extract oxygen from maternal HbA across the placenta."]','A','HbF higher affinity = fetus can extract O2 from mother blood. After birth, HbF is replaced by HbA by ~6 months of age.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','hard','flashcard','What is methaemoglobin and why is it unable to carry oxygen?','["Methaemoglobin is haemoglobin in which iron has been oxidised from ferrous (Fe2+) to ferric (Fe3+) state. Fe3+ cannot bind oxygen, so methaemoglobin is non-functional for O2 transport. It is normally kept at less than 1% by NADH-methaemoglobin reductase (cytochrome b5 reductase) in RBCs. Drugs (dapsone, nitrates, prilocaine) and toxins can cause methaemoglobinaemia, presenting with cyanosis despite normal PaO2."]','A','Methaemoglobin = Fe3+ = no O2 carrying. Treatment: methylene blue (requires G6PD-intact RBCs for NADPH-dependent reduction).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','medium','flashcard','What factors shift the oxygen-haemoglobin dissociation curve to the right (Bohr effect)?','["The O2-Hb dissociation curve shifts RIGHT (decreased Hb-O2 affinity, increased O2 unloading) with: (1) Increased CO2 (hypercapnia); (2) Increased H+ / decreased pH (acidosis); (3) Increased temperature; (4) Increased 2,3-bisphosphoglycerate (2,3-BPG). These conditions occur in metabolically active tissues, promoting O2 delivery where most needed. A left shift (increased affinity) occurs with alkalosis, hypothermia, decreased CO2, and low 2,3-BPG."]','A','Mnemonic for right shift: CADET — CO2 up, Acidosis, DPG up, Exercise (temp up). A right shift is physiologically appropriate in exercising tissue.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','easy','flashcard','What are the steps in haemoglobin biosynthesis?','["Haemoglobin synthesis steps: (1) Succinyl-CoA (from Krebs cycle) + glycine → pyrrole molecule; (2) Four pyrroles combine → protoporphyrin IX; (3) Protoporphyrin IX + Fe2+ → heme molecule; (4) Heme + globin polypeptide (from ribosomes) → haemoglobin chain (alpha or beta); (5) Two alpha chains + two beta chains combine loosely → haemoglobin A. Synthesis begins in polychromatophil erythroblasts and continues through the reticulocyte stage."]','A','Key starting materials: succinyl-CoA and glycine. Iron must be in ferrous (Fe2+) form. Deficiency of iron → microcytic hypochromic anaemia.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','medium','flashcard','What happens to haemoglobin after RBC destruction?','["When RBCs are destroyed, haemoglobin is phagocytised by macrophages (Kupffer cells in liver, spleen and bone marrow macrophages). Iron is liberated and returned to blood bound to transferrin for reuse (bone marrow for new Hb synthesis or liver/tissues for ferritin storage). The porphyrin portion of heme is converted through several stages into the bile pigment bilirubin, which is released into blood and excreted by the liver into bile."]','A','Heme catabolism: Heme → biliverdin → bilirubin → conjugated bilirubin (liver) → urobilinogen (gut). Elevated unconjugated bilirubin = haemolysis or impaired conjugation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','hard','flashcard','What is hereditary spherocytosis and how does the RBC shape defect cause anaemia?','["In hereditary spherocytosis, a defect in membrane cytoskeletal proteins (e.g., spectrin, ankyrin) causes RBCs to adopt a spherical rather than biconcave shape. Spherocytes lack the loose baglike membrane structure of normal biconcave discs, so they cannot deform during passage through the narrow (3-um) splenic trabeculae. This leads to splenic trapping and destruction (extravascular haemolysis), resulting in haemolytic anaemia with splenomegaly and jaundice."]','A','Spherocytes fail the osmotic fragility test (lyse at lower NaCl concentrations). Splenectomy is curative but leaves patients susceptible to encapsulated organisms.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','easy','flashcard','What are the six types of white blood cells and their normal percentages in blood?','["The six WBC types and approximate normal percentages: Neutrophils 62%, Lymphocytes 30%, Monocytes 5.3%, Eosinophils 2.3%, Basophils 0.4%, Plasma cells (occasional). Total WBC count: ~7000 per microlitre. Granulocytes (neutrophils, eosinophils, basophils) are polymorphonuclear cells with a granular appearance."]','A','Mnemonic: Never Let Monkeys Eat Bananas — Neutrophils, Lymphocytes, Monocytes, Eosinophils, Basophils (in order of frequency).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','medium','flashcard','What are the primary functions of neutrophils and how do they reach sites of infection?','["Neutrophils are the first responders to bacterial infection. They: (1) move by amoeboid motion through tissues; (2) undergo diapedesis through capillary walls; (3) are attracted to infection sites by chemotaxis (moving along concentration gradients of chemotactic substances from bacteria, damaged tissue, and complement products). Each neutrophil can phagocytise 3-20 bacteria; lysosomes fuse with the phagosome and bactericidal agents (superoxide, H2O2, hydroxyl ions, hypochlorite via myeloperoxidase) kill the ingested organisms."]','A','Neutrophil lifespan: 4-8 hours in blood, 4-5 days in tissues. Neutrophilia (>25,000/uL) reflects bone marrow mobilisation during acute infection.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','medium','flashcard','How do macrophages differ from neutrophils in their phagocytic capacity and longevity?','["Macrophages (derived from blood monocytes that enter tissues) are far more powerful phagocytes: they can phagocytise up to ~100 bacteria (vs. 3-20 for neutrophils), engulf much larger particles (whole RBCs, malarial parasites), contain lipases to digest lipid-coated bacteria like tuberculosis bacilli, and survive for months in tissues. Monocytes spend only 10-20 hours in blood before entering tissues, where they swell up to fivefold (to 60-80 um) and become fully capable macrophages."]','A','TB bacteria have lipid coats that resist neutrophil enzymes — only macrophage lipases can break them down. Macrophages are long-lived tissue sentinels.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','medium','flashcard','What is the role of eosinophils in host defence?','["Eosinophils (~2% of WBCs) are weak phagocytes especially important against parasitic infections. They cannot phagocytise most parasites (too large) but attach to them via surface molecules and release: (1) hydrolytic enzymes from granules; (2) reactive oxygen species; (3) major basic protein — a highly larvicidal polypeptide. Eosinophils also accumulate at allergic reaction sites and detoxify inflammatory substances released by mast cells and basophils."]','A','Eosinophilia = parasites or allergy. Eosinophils fight parasites and modulate allergic inflammation — they are not strong anti-bacterial cells.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','medium','flashcard','What substances do basophils and mast cells release and what is their role in allergic reactions?','["Basophils and mast cells release: heparin (anticoagulant), histamine, bradykinin, serotonin, slow-reacting substance of anaphylaxis (mixture of leukotrienes), and lysosomal enzymes. In allergy, IgE antibodies bind to mast cell/basophil surfaces. When specific antigen binds IgE, cross-linking triggers degranulation and massive release of these substances, causing vasodilation, increased vascular permeability, smooth muscle contraction, and mucus secretion — the cardinal features of allergic reactions and anaphylaxis."]','A','IgE + antigen + mast cell = allergic response. Basophils circulate in blood; mast cells reside in tissues (especially around capillaries in lungs and liver).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','easy','flashcard','What is the lifespan of granulocytes, monocytes, and lymphocytes in the blood?','["Granulocytes: 4-8 hours circulating in blood, then 4-5 days in tissues (shorter during active infection). Monocytes: 10-20 hours in blood before migrating to tissues where they become macrophages and live for months. Lymphocytes: circulate continuously through blood and lymphatics; lifespan varies from weeks to months. Bone marrow stores approximately a 6-day supply of granulocytes."]','A','Short-lived granulocytes = rapid first response; long-lived macrophages = chronic immune surveillance; lymphocytes = adaptive immune memory.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','hard','flashcard','Describe the process of opsonisation and why it enhances phagocytosis.','["Opsonisation is the coating of a pathogen with antibodies (and/or complement fragment C3b) to make it more susceptible to phagocytosis. Antibodies bind to bacterial surface antigens and combine with C3 from the complement cascade. C3b attaches to complement receptors on the phagocyte membrane, triggering strong binding and initiating phagocytosis. Without opsonisation, many bacteria with smooth surfaces or protective protein coats resist phagocytosis."]','A','Opsonins = make the pathogen tasty for phagocytes. IgG is the main opsonising antibody; C3b is the main complement opsonin. Asplenic patients are vulnerable to encapsulated organisms.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','medium','flashcard','What is the monocyte-macrophage (reticuloendothelial) system and where is it found?','["The monocyte-macrophage system comprises all monocytes, mobile macrophages, fixed tissue macrophages, and some specialised endothelial cells. Key locations: histiocytes in skin/subcutaneous tissue; alveolar macrophages in lungs; Kupffer cells lining liver sinusoids (clear gut-derived bacteria from portal blood in <0.01 seconds); macrophages in spleen red pulp (remove old RBCs); macrophages lining lymph node sinuses. All originate from monocytic stem cells in bone marrow."]','A','Kupffer cells are among the most active phagocytes. Spleen macrophages remove senescent RBCs. Failure of this system leads to bacteraemia.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','hard','flashcard','What is leukopenia and what are its clinical consequences?','["Leukopenia is a dangerously low WBC count from bone marrow failure (e.g., radiation, toxic chemicals like benzene, chloramphenicol, certain barbiturates). Without adequate WBCs, bacteria that normally coexist with mucosal surfaces invade deeper tissues. Within 2 days of severe leukopenia, oral and colonic ulcers appear; bacteria rapidly invade blood. Without treatment, death can occur within 1 week of acute total leukopenia."]','A','Leukopenia = removed immune shield. Recovery requires surviving stem cells to regenerate marrow (weeks to months). Broad-spectrum antibiotics are essential bridging therapy.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','medium','flashcard','What is chemotaxis and what substances induce it in neutrophils and macrophages?','["Chemotaxis is directed movement of WBCs toward infection/inflammation, driven by concentration gradients of chemotactic substances. Major chemotactic agents: (1) bacterial and viral toxins; (2) degradation products of inflamed tissue; (3) complement reaction products (e.g., C5a); (4) plasma clotting products; (5) inflammatory cytokines (TNF, IL-1). Chemotaxis is effective up to 100 um from inflamed tissue — sufficient to recruit cells from nearby capillaries."]','A','C5a is the most potent complement-derived chemoattractant. Defects in chemotaxis (e.g., Chediak-Higashi syndrome) cause recurrent bacterial infections.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','easy','flashcard','What are platelets, where are they produced, and what is their normal count?','["Platelets (thrombocytes) are minute anucleate disc-shaped cell fragments 1-4 micrometres in diameter. They are produced in the bone marrow by fragmentation of megakaryocytes — extremely large haematopoietic cells that fragment in the marrow or as they pass through pulmonary capillaries. Normal platelet count: 150,000-450,000/uL (average ~300,000). Platelets are replaced approximately every 10 days (~30,000 formed per uL of blood daily)."]','A','Megakaryocytes make mini-platelets. Thrombopoietin (TPO), produced by the liver, is the principal growth factor driving megakaryocyte development.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','medium','flashcard','What functional components are found in the platelet cytoplasm?','["Platelet cytoplasm contains: (1) Actin, myosin, and thrombosthenin — contractile proteins enabling clot retraction; (2) Endoplasmic reticulum and Golgi remnants that synthesise enzymes and store Ca2+; (3) Mitochondria and enzymes forming ATP and ADP; (4) Enzyme systems for prostaglandin synthesis (including thromboxane A2); (5) Fibrin-stabilising factor (Factor XIII); (6) Growth factor for vascular repair (PDGF). The surface glycoprotein coat repels normal endothelium but adheres to injured areas and collagen."]','A','Platelets are anucleate but metabolically active. Surface glycoproteins GPIb and GPIIb/IIIa mediate adhesion and aggregation respectively.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','medium','flashcard','Describe the mechanism of platelet plug formation (primary haemostasis).','["When a vessel is injured: (1) Collagen and von Willebrand factor (vWF) are exposed in the subendothelium; (2) Platelets adhere to vWF via glycoprotein Ib (GPIb) receptor — GPIb-vWF-collagen bridge; (3) Adhered platelets activate: they swell, extend pseudopods, and release ADP, platelet-activating factor (PAF), and thromboxane A2 (TXA2) from granules; (4) ADP, PAF, and TXA2 activate nearby platelets; (5) Activated platelets aggregate via GPIIb/IIIa receptors binding fibrinogen; (6) A loose platelet plug forms, later strengthened by fibrin from the coagulation cascade."]','A','GPIb = adhesion (binds vWF). GPIIb/IIIa = aggregation (binds fibrinogen). Bernard-Soulier = GPIb deficiency; Glanzmann thrombasthenia = GPIIb/IIIa deficiency.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','medium','flashcard','What is the role of thromboxane A2 (TXA2) and prostacyclin (PGI2) in platelet physiology?','["TXA2 (released by activated platelets): potent vasoconstrictor and platelet activator — promotes platelet aggregation and reinforces the haemostatic plug. PGI2/prostacyclin (released by healthy endothelial cells): potent vasodilator and platelet aggregation inhibitor — prevents inappropriate clotting on intact endothelium. The balance between TXA2 and PGI2 determines whether platelets aggregate at a given site. Aspirin irreversibly inhibits COX-1 (the enzyme for TXA2 synthesis in platelets), shifting the balance towards PGI2."]','A','TXA2 vs PGI2 = yin and yang of haemostasis. Aspirin inhibits both, but platelets cannot regenerate COX-1 (no nucleus), while endothelial cells can — net anti-platelet effect.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','hard','flashcard','What is thrombocytopenia and at what platelet count do clinical complications arise?','["Thrombocytopenia is a platelet count below normal (<150,000/uL). Clinical thresholds: below 30,000/uL — increased surgical bleeding risk; below 30,000/uL — spontaneous bleeding may occur; below 10,000/uL — frequently lethal. Features include petechiae, purpura, and mucous membrane bleeding. Major causes: decreased marrow production (infections, nutrient deficiency, myelodysplasia); peripheral destruction by antibodies (ITP); splenic sequestration (splenomegaly); consumption (DIC); dilution (massive transfusion)."]','A','ITP (immune thrombocytopenic purpura) is the most common cause — anti-platelet IgG destroys platelets. Splenectomy helps because the spleen removes IgG-coated platelets.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','medium','flashcard','What is clot retraction and how do platelets contribute to it?','["Clot retraction is the contraction of a blood clot expressing serum within 20-60 minutes of clot formation. Platelets trapped in the fibrin meshwork contribute by: (1) activating contractile proteins (thrombosthenin, actin, myosin) which contract platelet spicules attached to fibrin; (2) releasing fibrin-stabilising factor (Factor XIII) to cross-link fibrin; (3) providing Ca2+ from internal stores that activates contraction. Clot retraction pulls vessel wall edges together, further reducing haemorrhage."]','A','Failure of clot retraction suggests thrombocytopenia. Serum = plasma minus fibrinogen and clotting factors consumed during clotting.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','easy','flashcard','What is the role of von Willebrand factor (vWF) in haemostasis?','["Von Willebrand factor (vWF) is a large plasma protein that serves as an adhesion bridge between subendothelial collagen and platelet glycoprotein Ib (GPIb) surface receptors. When the endothelium is damaged, exposed subendothelial collagen binds vWF, which then tethers platelets via GPIb to initiate platelet adhesion (the first step of primary haemostasis). vWF also acts as a carrier for Factor VIII in the circulation, protecting it from degradation."]','A','vWF deficiency = von Willebrand disease (most common inherited bleeding disorder). Features mucocutaneous bleeding unlike haemophilia which causes deep bleeding.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','hard','flashcard','What is the role of ADP in platelet activation and aggregation?','["ADP released from the dense granules of activated platelets acts on P2Y1 and P2Y12 receptors on neighbouring platelets, causing them to activate and aggregate. ADP promotes shape change, GPIIb/IIIa receptor activation (which then binds fibrinogen to bridge platelets), and further granule release — a positive feedback cycle that amplifies the platelet plug. Clopidogrel and ticagrelor block P2Y12 receptors, used clinically to prevent arterial thrombosis."]','A','ADP = amplifier of platelet activation. P2Y12 is the key target for antiplatelet drugs in ACS management (clopidogrel, prasugrel, ticagrelor).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','medium','flashcard','What is thrombopoiesis and what regulates it?','["Thrombopoiesis is production of platelets from megakaryocytes in bone marrow. Megakaryocytes develop from MHSC via CFU-M. They undergo endomitosis (DNA replication without cell division), becoming polyploid giant cells whose cytoplasm fragments into thousands of platelets. The primary regulator is thrombopoietin (TPO), produced mainly by the liver. TPO levels rise when platelets are low (less TPO consumed by platelets) and fall when counts are high — a feedback regulation mechanism."]','A','TPO = liver-produced thrombopoiesis regulator. Low platelets → less TPO consumed → more free TPO → more megakaryocytes → more platelets. Used clinically as romiplostim/eltrombopag in ITP.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','medium','flashcard','How does vascular smooth muscle contraction contribute to haemostasis?','["Immediately after vessel injury, vascular smooth muscle contracts (vasospasm), reducing blood flow. Three mechanisms contribute: (1) Local myogenic spasm from direct trauma; (2) Local autacoid factors from traumatised tissue, endothelium, and platelets (especially thromboxane A2); (3) Nervous reflexes triggered by pain nerve impulses from injured tissue. Vasospasm can last minutes to hours, providing critical time for platelet plug formation and coagulation. The more severe the vessel trauma, the greater the degree of vasospasm."]','A','Vasospasm is the FIRST step of haemostasis — it buys time. TXA2 from platelets powerfully amplifies local vasoconstriction.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','easy','flashcard','What are the three essential steps of blood coagulation?','["The three essential steps of coagulation are: (1) Formation of prothrombin activator — a cascade involving more than 12 coagulation factors, initiated by vessel trauma or blood contact with collagen; (2) Prothrombin activator catalyses conversion of prothrombin (Factor II) to thrombin; (3) Thrombin acts as an enzyme to convert fibrinogen (Factor I) into fibrin monomers that polymerise into fibrin fibers, forming the clot meshwork that traps platelets and blood cells."]','A','The rate-limiting step is formation of prothrombin activator. Once formed, conversion to thrombin and then fibrin occurs within seconds.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','medium','flashcard','Describe the extrinsic pathway of coagulation.','["The extrinsic pathway is initiated by tissue trauma: (1) Traumatised tissue releases tissue factor (Factor III/tissue thromboplastin) — composed of phospholipids and a lipoprotein; (2) Tissue factor complexes with Factor VII + Ca2+ → activates Factor X (Xa); (3) Activated Factor X combines with Factor V, platelet phospholipids, and Ca2+ → forms prothrombin activator complex; (4) Prothrombin activator converts prothrombin → thrombin in seconds. The extrinsic pathway can complete in as little as 15 seconds."]','A','Extrinsic = external tissue triggers it (tissue factor). The PT/prothrombin time test measures this pathway. Factor VII has the shortest half-life of all clotting factors.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','medium','flashcard','Describe the intrinsic pathway of coagulation.','["The intrinsic pathway begins with blood trauma or contact with subendothelial collagen: (1) Factor XII is activated (XIIa) on contact with collagen; platelets release phospholipids; (2) Factor XIIa activates Factor XI (XIa) — requires HMW kininogen and prekallikrein; (3) Factor XIa activates Factor IX (IXa) via Ca2+; (4) Factor IXa + Factor VIIIa + platelet phospholipids + Ca2+ → activates Factor X (Xa); (5) Factor Xa + Factor Va + phospholipids → prothrombin activator → thrombin. This pathway takes 1-6 minutes."]','A','Intrinsic = internal blood components trigger it (contact activation). Measured by APTT. Haemophilia A = Factor VIII deficiency; Haemophilia B = Factor IX deficiency.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','medium','flashcard','What is the role of thrombin beyond converting fibrinogen to fibrin?','["Thrombin has multiple positive feedback roles beyond fibrin formation: (1) Activates Factor V (accelerating prothrombin conversion); (2) Activates Factor VIII (accelerating Factor X activation in the intrinsic pathway); (3) Activates Factor XIII (fibrin-stabilising factor) → covalent cross-linking of fibrin; (4) Acts proteolytically on prothrombin to form more thrombin; (5) Promotes platelet aggregation. Once formed, thrombin creates a powerful positive feedback driving further clot formation."]','A','Thrombin = master amplifier of coagulation. It activates Factors V, VIII, XIII, and more thrombin. Small amounts of initial thrombin explosively generate a full clot.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','medium','flashcard','What is the role of calcium ions in the coagulation cascade?','["Calcium ions (Ca2+, Factor IV) are required for nearly all steps of the coagulation cascade except the first two steps of the intrinsic pathway (activation of Factors XII and XI). Ca2+ acts as a cofactor promoting or accelerating clotting reactions. In the living body, Ca2+ rarely falls low enough to impair clotting. In vitro, clotting is prevented by Ca2+ chelation using citrate (binds Ca2+) or oxalate (precipitates Ca2+) — used in blood collection tubes."]','A','Citrate is used in blood bank storage to prevent clotting — it is non-toxic and metabolised rapidly by the liver. EDTA also works by chelating Ca2+.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','hard','flashcard','What is the role of vitamin K in coagulation and which factors does it affect?','["Vitamin K is required by a hepatic carboxylase enzyme that adds a carboxyl group to glutamic acid residues on five coagulation factors: prothrombin (II), Factor VII, Factor IX, Factor X, and Protein C. This carboxylation is essential for the factors to bind Ca2+ and phospholipid surfaces to function. During the reaction, vitamin K is oxidised and must be recycled by VKORC1. Warfarin inhibits VKORC1, blocking vitamin K recycling and causing deficiency of these factors."]','A','Mnemonic: Factors II, VII, IX, X are vitamin K-dependent (also Proteins C and S). Warfarin inhibits VKORC1 → decreases active vitamin K → inactive clotting factors.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','hard','flashcard','What is fibrin stabilising factor (Factor XIII) and how does it strengthen the clot?','["Factor XIII is present in small amounts in plasma and is released from platelets. It is activated by thrombin. Once activated, Factor XIIIa acts as a transglutaminase to form covalent bonds between fibrin monomer molecules and multiple cross-linkages between adjacent fibrin fibers. This converts the initial weak hydrogen-bond-held fibrin lattice into a strong three-dimensional covalent meshwork. Without cross-linking, clots are fragile and dissolve easily."]','A','Fibrin first forms via weak H-bonds (soluble) → Factor XIIIa creates covalent bonds → insoluble cross-linked fibrin. Factor XIII deficiency causes delayed bleeding (clot forms but dissolves).','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','easy','flashcard','What are the synonyms for clotting Factors VIII and IX, and what bleeding disorder results from deficiency of each?','["Factor VIII — antihemophilic factor (AHF): deficiency causes Haemophilia A (classic haemophilia), ~85% of haemophilia cases; X-linked recessive, ~1 in 10,000 males. Factor IX — Christmas factor: deficiency causes Haemophilia B (Christmas disease), ~15% of cases; also X-linked recessive. Both present with deep bleeding into joints (haemarthroses) and muscles after minor trauma."]','A','Haemophilia A = 8 letters in VIII = Factor 8. Haemophilia B = 9 letters in IX = Factor 9 (Christmas factor — named after the first patient, Stephen Christmas).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','medium','flashcard','What is fibrinogen, where is it produced, and what triggers its conversion to fibrin?','["Fibrinogen (Factor I) is a high-molecular-weight plasma protein (MW ~340,000) produced by the liver at concentrations of 100-700 mg/dL. Its large size prevents leakage into interstitial fluid under normal conditions. Thrombin removes four low-MW peptides from fibrinogen, generating fibrin monomer. Fibrin monomers spontaneously polymerise into long fibrin fibers, then cross-linked by Factor XIIIa into a stable clot. Liver disease reduces fibrinogen production."]','A','Fibrinogen → Fibrin: thrombin cleaves fibrinopeptides A and B. Monitoring fibrinogen levels is useful in DIC where it is consumed rapidly.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','medium','flashcard','How do the extrinsic and intrinsic pathways interact during vessel injury?','["After vessel rupture, both pathways are activated simultaneously and interact. Tissue factor initiates the extrinsic pathway (fast: 15 seconds). Contact of Factor XII and platelets with subendothelial collagen initiates the intrinsic pathway (slower: 1-6 minutes). The extrinsic pathway is explosive and limited only by tissue factor quantity and Factors X, VII, and V. Thrombin generated by the extrinsic pathway also activates Factor VIII, further accelerating the intrinsic pathway — demonstrating constant interaction between the two systems."]','A','Both pathways converge on Factor X activation → common pathway → thrombin → fibrin. In vivo, TF-VIIa also activates Factor IX, linking extrinsic to intrinsic pathway.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','medium','flashcard','What is plasminogen, how is it activated, and what does plasmin do?','["Plasminogen (profibrinolysin) is an inactive plasma euglobulin trapped in forming blood clots. It is activated to plasmin (fibrinolysin) primarily by tissue plasminogen activator (t-PA) released slowly by injured vascular endothelium. Plasmin is a proteolytic enzyme that digests fibrin fibers and other coagulation proteins — fibrinogen, Factor V, Factor VIII, prothrombin, and Factor XII — causing clot lysis (fibrinolysis). This mechanism reopens small vessels that would otherwise remain permanently occluded by minor clots."]','A','t-PA is released slowly, so lysis occurs days after clotting — once healing is underway. Recombinant t-PA (alteplase) is used clinically to lyse coronary and pulmonary thrombi.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','medium','flashcard','What is antithrombin III and how does it prevent coagulation?','["Antithrombin III (AT-III) is an alpha-globulin that inactivates free thrombin in the blood by binding to it, blocking thrombin action on fibrinogen and inactivating thrombin itself over 12-20 minutes. AT-III also inactivates other activated coagulation factors (Factors IXa, Xa, XIa, XIIa). Heparin dramatically enhances AT-III activity — the heparin-AT-III complex removes thrombin and other activated factors almost instantaneously (100-1000-fold increased potency)."]','A','AT-III = heparin cofactor. Without AT-III (hereditary AT-III deficiency), patients have recurrent thromboembolism and are resistant to heparin therapy.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','medium','flashcard','What is the role of Protein C in anticoagulation?','["Protein C is a vitamin K-dependent anticoagulant protein activated by the thrombin-thrombomodulin complex on endothelial cell surfaces. Once activated, Protein C (with its cofactor Protein S) inactivates the activated forms of Factors V (Va) and VIII (VIIIa), dramatically reducing the rate of thrombin generation. This creates a negative feedback: thrombin activates Protein C, which then limits further thrombin production. Deficiency of Protein C or S causes a hypercoagulable state with recurrent DVT and PE."]','A','Thrombomodulin on endothelial cells converts thrombin from a procoagulant to an anticoagulant (activates Protein C). Protein C + Protein S = natural anticoagulant pair.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','medium','flashcard','How does heparin work as an anticoagulant and where is it produced in the body?','["Heparin is a highly negatively charged conjugated polysaccharide produced naturally by mast cells (largest quantities in pericapillary connective tissue in lungs and liver) and basophils. By itself, heparin has little anticoagulant effect; however, when combined with antithrombin III, the heparin-AT-III complex removes thrombin and other activated factors (IXa-XIIa) almost instantaneously, increasing AT-III potency 100-1000-fold. Pharmacologically, heparin is injected in larger concentrations for anticoagulation."]','A','Heparin is most concentrated around lung and liver capillaries — to prevent clotting of emboli in these high-flow organs. Half-life in blood: ~1.5-4 hours (destroyed by heparinase).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','hard','flashcard','How does warfarin work and what is its mechanism of action at the molecular level?','["Warfarin inhibits VKORC1 (vitamin K epoxide reductase complex 1), the enzyme responsible for recycling oxidised, inactive vitamin K back to its active (reduced) form. Without active vitamin K, the hepatic carboxylase cannot add carboxyl groups to glutamic acid residues on vitamin K-dependent clotting factors (II, VII, IX, X) and anticoagulant Proteins C and S. These factors are produced but biologically inactive. Warfarin effect is delayed (~12-24 hours) because it must wait for existing active factors to be consumed."]','A','Warfarin: Protein C and S fall first (shortest half-lives) → transient hypercoagulable state. This is why heparin is bridged when starting warfarin.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','medium','flashcard','What endothelial factors prevent clotting under normal conditions?','["Normal endothelium prevents clotting through: (1) Smooth surface — prevents contact activation of Factor XII and platelets; (2) Glycocalyx — a mucopolysaccharide layer that repels clotting factors and platelets; (3) Thrombomodulin — binds thrombin, removing it from circulation and activating Protein C (which inhibits Factors Va and VIIIa); (4) Prostacyclin (PGI2) — vasodilator and platelet aggregation inhibitor; (5) Nitric oxide (NO) — vasodilator and platelet aggregation inhibitor. Endothelial damage removes all of these protections."]','A','Intact endothelium = anti-thrombotic. Damaged endothelium = pro-thrombotic. Loss of glycocalyx + thrombomodulin + PGI2/NO = Virchow endothelial injury component.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','hard','flashcard','What is disseminated intravascular coagulation (DIC) and why does it paradoxically cause bleeding?','["DIC is widespread activation of the clotting mechanism throughout the circulation, typically triggered by large amounts of tissue factor released into blood (septicaemia, major trauma, obstetric emergencies, malignancy). Numerous small clots form in peripheral vessels causing ischaemia and organ failure. Paradoxically, the patient then bleeds because widespread clotting consumes clotting factors and platelets (consumptive coagulopathy), leaving too few procoagulants for normal haemostasis. DIC is lethal in 35-50% of septicaemic shock cases."]','A','DIC = clot AND bleed simultaneously. Lab: low fibrinogen, low platelets, elevated D-dimers, prolonged PT and APTT. Treat the underlying cause first.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','medium','flashcard','What is the clinical significance of fibrin adsorbing thrombin during clot formation?','["During clot formation, approximately 85-90% of the thrombin generated adsorbs directly to the developing fibrin fibers. This adsorption: (1) limits the spread of thrombin into the surrounding blood; (2) prevents excessive clot propagation beyond the injury site. The remaining ~10-15% of free thrombin is rapidly inactivated by antithrombin III. Together, these mechanisms confine clotting to the local injury site."]','A','Most thrombin is trapped in the clot itself — a self-limiting mechanism. Failure of this mechanism contributes to propagating thrombus formation (e.g., in DVT).','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','easy','flashcard','What natural anticoagulant systems prevent clotting in normal blood vessels?','["The main natural anticoagulant systems are: (1) Smooth endothelial surface + glycocalyx — prevents contact activation; (2) Thrombomodulin — activates Protein C on endothelium; (3) Protein C/Protein S system — inactivates Factors Va and VIIIa; (4) Antithrombin III (+ heparin) — neutralises thrombin and other activated factors; (5) Fibrin itself — adsorbs 85-90% of thrombin; (6) PGI2 and NO from endothelium — inhibit platelet aggregation."]','A','Anticoagulants normally dominate → blood remains fluid. Injury tips the balance toward procoagulants → local clot forms. Inherited deficiencies of Proteins C/S or AT-III → thrombophilia.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','hard','flashcard','What is the prothrombin time (PT) test and what does it measure?','["The prothrombin time (PT) measures the integrity of the extrinsic coagulation pathway (Factors I, II, V, VII, X). Blood is collected in oxalate (preventing clotting), then tissue factor and excess Ca2+ are added. Time to clot formation is measured — normal PT is ~12 seconds. A prolonged PT indicates deficiency of extrinsic pathway factors (VII, X, V, II, or I) or vitamin K deficiency. The INR standardises PT values: normal INR = 0.9-1.3; warfarin therapy target = 2.0-3.0."]','A','PT/INR = extrinsic pathway test. APTT = intrinsic pathway test. Mixing studies help distinguish factor deficiency from inhibitor (e.g., lupus anticoagulant).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','easy','flashcard','What are the four ABO blood types and what antigens and antibodies does each carry?','["ABO blood types: Type O — no A or B antigens on RBCs; carries both anti-A and anti-B agglutinins in plasma. Type A — A antigen; carries anti-B agglutinins. Type B — B antigen; carries anti-A agglutinins. Type AB — both A and B antigens; carries no agglutinins. Approximate frequencies: O = 47%, A = 41%, B = 9%, AB = 3%. ABO agglutinins develop naturally from 2-8 months after birth, peaking at 8-10 years."]','A','O = universal donor (no antigens to trigger reaction); AB = universal recipient (no antibodies to react against donor antigens). Type O blood has BOTH anti-A AND anti-B.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','medium','flashcard','What is the Rh blood group system and what is the major clinical antigen?','["The Rh system has six common antigens: C, D, E, c, d, e. The most clinically important is the D antigen — a person with D antigen is Rh-positive; without it, Rh-negative. Prevalence: ~85% of whites, ~95% of blacks, and >95% of Asians are Rh-positive. Unlike ABO antibodies, Rh antibodies do NOT develop spontaneously — they require prior exposure to Rh-positive blood. Anti-D antibodies are IgG, allowing placental transfer to cause erythroblastosis fetalis in subsequent Rh-positive pregnancies."]','A','Rh antibodies are IgG (cross placenta) whereas ABO agglutinins are mainly IgM (cannot cross placenta). This is why Rh incompatibility — not ABO — causes haemolytic disease of the newborn.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','hard','flashcard','What is erythroblastosis fetalis (haemolytic disease of the newborn) and how is it prevented?','["Erythroblastosis fetalis occurs when an Rh-negative mother develops anti-D IgG antibodies after sensitisation by a previous Rh-positive pregnancy or transfusion. In subsequent Rh-positive pregnancies, IgG crosses the placenta, agglutinates foetal RBCs, causing haemolysis → severe anaemia, jaundice (bilirubin), and kernicterus (bilirubin deposition in neurons). Prevention: Anti-D immunoglobulin given to Rh-negative mothers at 28-30 weeks gestation and after delivery of Rh-positive baby — suppresses maternal anti-D antibody formation."]','A','First Rh-positive baby rarely affected (sensitisation occurs at delivery). Second and subsequent babies at increasing risk. Anti-D prophylaxis has dramatically reduced incidence.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','medium','flashcard','What happens during an ABO-incompatible transfusion reaction?','["When incompatible blood is transfused, recipient agglutinins bind donor RBC antigens → agglutination (clumping) → small vessel plugging. Subsequently, haemolysis occurs via complement activation (membrane attack complex) or phagocytosis of clumped cells → haemoglobinaemia → haemoglobinuria. Clinical consequences: acute kidney failure (haemoglobin precipitates in tubules + renal vasospasm + hypotension), jaundice, circulatory shock. Death can result from renal failure within 7-12 days if untreated."]','A','Recipient antibodies attack donor RBCs (not vice versa) — donor plasma is diluted by recipient plasma, but donor RBCs are exposed to full concentration of recipient antibodies.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','easy','flashcard','How are blood groups typed in the laboratory?','["Blood typing procedure: (1) Separate RBCs from plasma by centrifugation; (2) Dilute RBCs in saline; (3) Divide into two portions — mix one with anti-A serum, the other with anti-B serum; (4) Observe under microscope for agglutination: Type O — no agglutination with either; Type A — agglutination with anti-A only; Type B — agglutination with anti-B only; Type AB — agglutination with both. For Rh typing, RBCs are tested with anti-D serum — agglutination = Rh-positive."]','A','Forward grouping (test RBCs with known antisera) should be confirmed by reverse grouping (test plasma with known RBCs). Discrepancies between the two require investigation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','medium','flashcard','What is the genetic basis of the ABO blood group system?','["The ABO locus has three alleles: IA (A), IB (B), and IO (O). The O allele is functionless/recessive; A and B alleles are codominant. Six genotypes produce four phenotypes: OO → type O; OA or AA → type A; OB or BB → type B; AB → type AB. The A allele codes for a glycosyltransferase adding N-acetylgalactosamine to the H antigen; the B allele adds galactose instead. The O allele codes for a non-functional enzyme, so no modification occurs."]','A','Codominance: A and B are both expressed if present. O is recessive to both. Blood typing cannot always distinguish OA from AA — genotyping by PCR can.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','medium','flashcard','Why do ABO antibodies develop without prior blood exposure whereas Rh antibodies require sensitisation?','["ABO agglutinins develop naturally because type A and B antigens are widespread in nature — in food, bacteria, and the environment. From 2-8 months after birth, infants are exposed to these cross-reactive antigens and mount an immune response, producing antibodies against the A or B antigens absent from their own RBCs. In contrast, Rh antigens are not present in the environment, so anti-D antibodies only develop after deliberate exposure (transfusion of Rh-positive blood or foeto-maternal haemorrhage)."]','A','ABO antibodies = natural (no prior exposure needed). Rh antibodies = immune (require prior exposure). ABO mismatch is therefore more immediately dangerous in a first transfusion than Rh mismatch.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','hard','flashcard','Why does acute renal failure occur after a severe transfusion reaction?','["Acute renal failure after transfusion reaction has three mechanisms: (1) Renal vasoconstriction caused by toxic substances released from haemolysed RBCs and the antigen-antibody reaction; (2) Circulatory shock from loss of circulating RBCs, toxic haemolysis products, and immune reaction reducing cardiac output and renal perfusion; (3) Tubular obstruction — free haemoglobin leaking through glomeruli concentrates in tubules as water is reabsorbed, precipitating and blocking tubules. Haptoglobin can bind limited amounts of free Hb, but is overwhelmed in severe reactions."]','A','Tubular blockage by haemoglobin casts causes acute tubular necrosis. If complete renal shutdown persists, death within 7-12 days without dialysis. Prevention = correct pre-transfusion compatibility testing.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','medium','flashcard','What is the difference between agglutination and haemolysis in transfusion reactions?','["Agglutination is the clumping of RBCs caused by agglutinins cross-linking multiple RBCs by attaching to antigen sites on their surfaces. IgG antibodies have 2 binding sites; IgM have 10 binding sites per molecule. Agglutinated clumps plug small vessels. Haemolysis is the actual rupture of RBC membranes releasing haemoglobin into plasma. It can occur immediately via complement activation (membrane attack complex, mainly IgM antibodies called haemolysins) or be delayed as phagocytes destroy agglutinated cells over hours to days."]','A','Immediate intravascular haemolysis is less common but more dangerous than delayed extravascular haemolysis. High IgM titres (as in ABO mismatch) drive immediate haemolysis.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','easy','flashcard','What are the four major mechanisms of haemostasis and in what order do they occur?','["The four sequential haemostatic mechanisms after vessel injury: (1) Vascular constriction (vasospasm) — immediate local smooth muscle contraction reducing blood flow; (2) Platelet plug formation (primary haemostasis) — platelets adhere, activate, and aggregate to form a loose plug; (3) Blood coagulation (secondary haemostasis) — coagulation cascade forms fibrin reinforcing the platelet plug; (4) Fibrous tissue organisation — fibroblasts invade the clot over 1-2 weeks permanently sealing the vessel. Fibrinolysis may alternatively resolve the clot if no longer needed."]','A','Order: Vasoconstriction → Platelet plug → Coagulation → Fibrous repair (or fibrinolysis). Failure at any step = prolonged bleeding.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','easy','flashcard','How is dietary iron absorbed from the gastrointestinal tract?','["Iron is absorbed from all parts of the small intestine, predominantly from the duodenum. The liver secretes apotransferrin into bile; in the duodenum, apotransferrin binds free iron and haem-bound iron from haemoglobin and myoglobin in meat. This iron-apotransferrin complex binds to receptors on intestinal epithelial cell brush borders and is absorbed by pinocytosis. It is released into blood capillaries as plasma transferrin. Absorption rate is maximal only a few mg per day and is regulated by total body iron stores."]','A','Haem iron (from meat) is absorbed more efficiently than non-haem iron. Vitamin C enhances non-haem iron absorption by reducing Fe3+ to Fe2+. Phytates and tannins inhibit absorption.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','easy','flashcard','How is iron transported in the blood?','["When iron is absorbed from the small intestine, it immediately binds to the beta-globulin protein apotransferrin in the plasma, forming transferrin. Iron is loosely bound to transferrin and can be released to any tissue cell. Transferrin delivers iron to bone marrow erythroblasts by binding to transferrin receptors on their surface; the complex is internalised by endocytosis and iron is delivered to mitochondria where haem synthesis occurs. Normal transferrin is only 30-35% saturated with iron."]','A','Transferrin = iron blood taxi. Transferrin saturation <16% = iron deficiency. Serum ferritin and transferrin together diagnose iron status.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','medium','flashcard','How is iron stored in the body and what proteins are involved?','["Iron is stored in two forms: (1) Ferritin — iron bound to the protein apoferritin (MW ~460,000) in the cell cytoplasm. This is the primary, readily mobilisable storage form. Ferritin particles are dispersed and visible only by electron microscopy. (2) Hemosiderin — an insoluble condensed iron-apoferritin complex that forms when iron stores exceed apoferritin capacity. Visible as large particles under light microscopy. Storage sites: liver hepatocytes (main), reticuloendothelial cells of bone marrow and spleen."]','A','Serum ferritin reflects total body iron stores — 1 ug/L approximately 8 mg stored iron. Ferritin is also an acute phase reactant (rises in inflammation regardless of iron status).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','easy','flashcard','How is iron distributed across body compartments and what is the total body iron content?','["Total body iron: ~4-5 grams. Distribution: ~65% in haemoglobin (the largest pool); ~4% in myoglobin; ~1% in haem-containing enzymes (cytochromes, cytochrome oxidase, peroxidase, catalase); ~0.1% bound to transferrin in plasma; ~15-30% stored as ferritin and haemosiderin in reticuloendothelial system and liver. Daily iron requirement: men ~0.6 mg/day (faecal losses); women ~1.3 mg/day (additional menstrual losses of ~0.7 mg/day)."]','A','Most iron is in Hb — haemorrhage depletes iron rapidly. Women higher requirement explains why iron deficiency anaemia is far more common in premenopausal women.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','medium','flashcard','How is iron recycled when red blood cells are destroyed?','["When RBCs reach the end of their 120-day lifespan, they are destroyed by macrophages (Kupffer cells in liver, spleen macrophages, bone marrow macrophages). Haemoglobin is phagocytised; macrophages liberate iron from haem and store it as ferritin or haemosiderin. When plasma iron falls, ferritin-stored iron is mobilised and transported via transferrin to erythroblasts in the bone marrow (via transferrin receptor-mediated endocytosis) for new haemoglobin synthesis. The porphyrin portion is converted to bilirubin."]','A','Iron recycling is highly efficient — 20-25 mg/day recycled from senescent RBCs vs. only 1-2 mg absorbed daily from diet. The body hoards iron.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','hard','flashcard','How does the body regulate iron absorption to match iron stores?','["Total body iron is regulated primarily by controlling intestinal absorption rate. When iron stores are saturated, intestinal absorption markedly decreases. When stores are depleted, absorption can increase up to 5-fold or more. The principal regulator is hepcidin (a liver-derived peptide): high iron/inflammation → high hepcidin → degrades ferroportin (the basolateral iron exporter on enterocytes) → decreases iron entry into blood. Low iron → low hepcidin → ferroportin persists → increased absorption."]','A','Hepcidin is the master iron regulator. In anaemia of chronic disease, inflammatory cytokines raise hepcidin, trapping iron in macrophages and reducing absorption → functional iron deficiency.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','medium','flashcard','What is the clinical presentation and laboratory findings of iron deficiency anaemia?','["Iron deficiency anaemia presents with symptoms of anaemia (fatigue, pallor, exertional dyspnoea, tachycardia); in severe cases — koilonychia (spoon nails), angular cheilitis, glossitis, Plummer-Vinson syndrome (dysphagia). Blood film: microcytic (low MCV), hypochromic (low MCHC) RBCs — pale cells smaller than normal. Lab: low serum ferritin (depleted stores), low serum iron, elevated TIBC (total iron binding capacity), low transferrin saturation (<16%)."]','A','Microcytic hypochromic = think iron deficiency first. Check ferritin first (most sensitive store marker). TIBC rises in iron deficiency (more unfilled transferrin sites) but falls in anaemia of chronic disease.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','medium','flashcard','What is the role of transferrin receptors on erythroblasts in iron uptake?','["Erythroblasts in the bone marrow have high-affinity transferrin receptors on their surface. When plasma transferrin (carrying Fe3+) binds to these receptors, the transferrin-iron complex is internalised by endocytosis. Inside the cell, iron is released in acidic endosomes and delivered to mitochondria where it is incorporated into protoporphyrin IX to form haem. The recycled apotransferrin is returned to the plasma for reuse. Transferrin receptor expression is regulated by intracellular iron — low iron increases receptor expression to capture more transferrin."]','A','Serum soluble transferrin receptor (sTfR) rises in iron deficiency and is useful for distinguishing iron deficiency from anaemia of chronic disease (sTfR normal/low in ACD).','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','easy','flashcard','What is the difference between ferritin and hemosiderin as iron storage forms?','["Ferritin is the primary iron storage protein: iron (Fe3+) is stored within the protein shell of apoferritin (MW ~460,000). Ferritin particles are small and dispersed throughout the cytoplasm, visible only by electron microscopy. Iron is readily mobilised from ferritin when plasma iron falls. Hemosiderin is an insoluble condensed aggregate of iron and protein that forms when iron stores exceed ferritin capacity. Visible as large aggregates under light microscopy (Perls Prussian blue stain). Iron in hemosiderin is released more slowly."]','A','Serum ferritin = circulating marker of storage iron. Bone marrow biopsy Prussian blue stain shows absent stainable iron in iron deficiency. Hemosiderin excess = haemosiderosis/haemochromatosis.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','hard','flashcard','Why does chronic blood loss cause microcytic hypochromic anaemia rather than normocytic anaemia?','["In chronic blood loss (e.g., GI bleeding, menorrhagia), iron is lost faster than it can be absorbed (maximum intestinal absorption = only a few mg/day). As iron stores become depleted, inadequate iron is available for haemoglobin synthesis. RBCs produced have insufficient haemoglobin to fill the cell (haemoglobin concentration falls below the 34 g/100 ml maximum). The cell also shrinks because it is incompletely filled — producing microcytic (small) and hypochromic (pale) RBCs. Acute haemorrhage with adequate iron stores produces normocytic anaemia initially."]','A','Chronic blood loss = iron depletion → microcytic hypochromic. Acute blood loss = normal stores intact → normocytic. Time to iron-deficient erythropoiesis: months of negative iron balance.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','easy','flashcard','What is the role of the thymus gland in lymphocyte development?','["The thymus preprocesses T lymphocytes (T for thymus). Lymphoid progenitor cells migrating from the bone marrow enter the thymus where they rapidly divide and develop extreme diversity in antigen reactivity — thousands of T lymphocyte types, each specific for a different antigen. The thymus also eliminates (by apoptosis) any T lymphocytes that react against the body own tissue antigens — establishing self-tolerance and preventing autoimmunity. Preprocessed T lymphocytes then leave the thymus to populate peripheral lymphoid tissues."]','A','Thymus = T-cell school. Positive selection (useful TCRs retained) + negative selection (self-reactive clones deleted) = central tolerance. DiGeorge syndrome = thymic aplasia → no T cells → severe immunodeficiency.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','easy','flashcard','Where are B lymphocytes preprocessed and what is their primary function?','["B lymphocytes are preprocessed in the liver during mid-foetal life and in the bone marrow during late foetal life and after birth. The B designation originally referred to the bursa of Fabricius in birds where the equivalent preprocessing occurs. Once mature, B lymphocytes populate peripheral lymphoid tissues. When stimulated by antigen with T-helper cell assistance, B cells differentiate into plasma cells that produce antibodies (immunoglobulins). B lymphocytes are responsible for humoral immunity."]','A','B cells = Bursa-derived (birds) / Bone marrow (humans). B cells → plasma cells → antibodies. T cells → activated T cells → cell-mediated immunity.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','medium','flashcard','What are the functions of lymph nodes in the immune system?','["Lymph nodes are ovoid lymphoid organs distributed along lymphatic vessels. Their functions: (1) Filtration — afferent lymph passes through medullary sinuses lined with macrophages that phagocytise particulate matter (bacteria, debris) preventing systemic dissemination; (2) Immune surveillance — lymphocytes in germinal centres are activated by antigens carried in lymph, generating antibody responses and memory cells; (3) Lymphocyte recirculation — lymph node lymphocytes re-enter blood via efferent lymphatics → thoracic duct."]','A','Lymph nodes = filters AND immune activation sites. Lymphadenopathy (swollen nodes) occurs when nodes fight infection (reactive) or are infiltrated by malignant cells (lymphoma, metastasis).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','medium','flashcard','What are the functions of the spleen in the lymphoid and haematological systems?','["The spleen has dual functions: (1) Haematological — filters blood through the red pulp; RBCs squeeze through 3-um trabecular spaces (vs. 8-um RBC diameter), destroying old and abnormal RBCs; macrophages remove particulate antigens from blood; stores ~30% of the platelet pool; (2) Immunological — white pulp contains T cells and follicles with B cells; initiates immune responses to blood-borne antigens. The spleen is the only lymphoid organ that directly samples blood rather than lymph."]','A','Post-splenectomy: (1) Thrombocytosis (released platelet pool); (2) Howell-Jolly bodies on blood film (nuclear remnants in RBCs); (3) Susceptibility to encapsulated organisms (pneumococcus, meningococcus, Hib).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','medium','flashcard','What is MALT (mucosa-associated lymphoid tissue) and where is it found?','["MALT is a diffuse system of lymphoid tissue found in mucosal surfaces. Key locations: (1) Gut-associated lymphoid tissue (GALT) — Peyer patches in the ileum, appendix, colonic follicles; (2) Bronchus-associated lymphoid tissue (BALT) — along the respiratory tract; (3) Tonsils and adenoids — in the pharynx (Waldeyer ring); (4) Lacteals in intestinal villi. MALT contains B cells, T cells, and macrophages positioned to intercept antigens entering via mucosal surfaces. It generates secretory IgA, the dominant mucosal immunoglobulin."]','A','MALT is the first lymphoid encounter for most ingested/inhaled antigens. Secretory IgA neutralises pathogens without triggering inflammation — important in mucosal tolerance.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','hard','flashcard','How do T lymphocytes contribute to cell-mediated immunity and what are the key T cell subtypes?','["T lymphocytes mediate cell-mediated immunity through several subtypes: (1) T-helper (CD4+) cells — orchestrate immune responses by releasing cytokines (IL-2, IL-4, IFN-gamma) that activate B cells, cytotoxic T cells, and macrophages; (2) Cytotoxic T (CD8+) cells — directly kill virus-infected cells, tumour cells, and foreign graft cells by releasing perforin and granzymes; (3) Regulatory T cells (Tregs) — suppress immune responses to prevent autoimmunity; (4) Memory T cells — long-lived cells enabling rapid response to repeat antigen exposure."]','A','CD4 = T-helper (count used to stage HIV). CD8 = cytotoxic T cells. IL-2 drives T cell proliferation — blocked by cyclosporine/tacrolimus (immunosuppression for transplants).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','medium','flashcard','What is the difference between humoral and cell-mediated immunity?','["Humoral immunity is mediated by B lymphocytes/plasma cells that produce circulating antibodies (immunoglobulins). Antibodies neutralise toxins, opsonise bacteria, and activate complement. Effective against extracellular pathogens, toxins, and viruses (before cell entry). Cell-mediated immunity is mediated by activated T lymphocytes. Effective against intracellular pathogens (viruses, mycobacteria, fungi), tumour cells, and transplanted tissue. It involves direct cell killing (cytotoxic T cells), delayed hypersensitivity, and macrophage activation."]','A','Humoral = antibodies (B cells). Cell-mediated = T cells. HIV destroys CD4 T-helper cells → collapses both arms (no T-helper = impaired B cell and CD8 responses).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','medium','flashcard','How do lymphocytes continuously circulate through the body?','["Lymphocytes enter the blood continuously via drainage of lymph from lymph nodes and other lymphoid tissues through the thoracic duct into the subclavian vein. After a few hours circulating in blood, they exit through post-capillary venules (high endothelial venules) into lymphoid tissues and interstitium by diapedesis/extravasation. They then re-enter lymphatic vessels and drain back through lymph nodes into the blood — a continuous recirculation loop. This ensures lymphocytes sample antigens throughout the body and can rapidly localise to sites of infection."]','A','Lymphocyte recirculation ensures immune surveillance across all tissues. Memory cells recirculate preferentially to the tissues where they were originally activated via tissue homing receptors.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','easy','flashcard','What is the distinction between primary and secondary lymphoid tissue in humans?','["Primary (central) lymphoid tissues are where lymphocytes develop and mature: Bone marrow — site of all blood cell production including B lymphocyte maturation; Thymus — site of T lymphocyte maturation and selection. Secondary (peripheral) lymphoid tissues are where mature lymphocytes encounter antigens and initiate immune responses: Lymph nodes, Spleen, MALT (tonsils, Peyer patches, appendix, BALT). Lymphocytes produced in primary tissues populate secondary tissues where they are activated by antigen-presenting cells."]','A','Primary = education (bone marrow + thymus). Secondary = action (lymph nodes + spleen + MALT). Developing lymphocytes in primary tissue undergo selection; only useful, non-self-reactive cells graduate to secondary tissue.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','hard','flashcard','What happens to antigen-stimulated B lymphocytes in lymphoid tissue?','["When a B lymphocyte encounters its specific antigen (typically with T-helper cell co-stimulation), it undergoes clonal expansion and differentiates into: (1) Plasma cells — large antibody-secreting cells that produce thousands of immunoglobulin molecules per second; plasma cells are terminally differentiated and short-lived; (2) Memory B cells — long-lived cells that persist and enable a faster, stronger secondary immune response upon re-exposure to the same antigen. Germinal centres in lymph node follicles are sites of B cell proliferation, affinity maturation (somatic hypermutation), and isotype class switching."]','A','Germinal centres = B cell reaction centres. Somatic hypermutation → affinity maturation (better antibodies over time). Class switching → IgM → IgG/IgA/IgE depending on cytokine environment.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed');
